begin;
do $$
declare w uuid:=gen_random_uuid();other uuid:=gen_random_uuid();a uuid:=gen_random_uuid();t uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();dev uuid:=gen_random_uuid();td uuid:=gen_random_uuid();ts uuid:=gen_random_uuid();gid uuid:=gen_random_uuid();gid2 uuid:=gen_random_uuid();mid uuid:=gen_random_uuid();mid2 uuid:=gen_random_uuid();oid uuid:=gen_random_uuid();task uuid:=gen_random_uuid();cid uuid:=gen_random_uuid();vid uuid;owner uuid;p jsonb;r jsonb;s jsonb;before_order jsonb;failed boolean;passed int:=0;
begin
 insert into auth.users(id,email) values(a,'fleet-admin-'||a||'@example.invalid'),(t,'fleet-tech-'||t||'@example.invalid');insert into auth.sessions(id,user_id) values(sid,a),(ts,t);
 insert into private.workshops(id,name) values(w,'Fictional fleet'),(other,'Fictional fleet isolation');insert into private.members values(w,a,'Admin','admin',true,true),(w,t,'Tech','technician',false,true),(other,a,'Admin','admin',true,true);
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sid)::text,true);s:=public.device_snapshot(w,dev);
 r:=public.apply_operation(w,dev,jsonb_build_object('id',gen_random_uuid(),'orderId',oid,'actorId',a,'kind','receive','baseRevision',0,'at',now(),'payload',jsonb_build_object('plate','9372FIC','country','ES','vin','FICTIONAL-FLEET','vehicle','Fictional','engine','2020','client','Fictional owner','phone','','km',128000,'symptom','Fictional symptom','tasks',jsonb_build_array(jsonb_build_object('id',task,'title','Diagnosis','assignees',jsonb_build_array(t),'estimateMinutes',30)))));if r->>'status'<>'accepted' then raise exception 'Source fixture';end if;
 s:=public.device_snapshot(w,dev);before_order:=s->'orders'->0;vid:=(before_order->>'vehicleId')::uuid;owner:=(before_order->>'ownerId')::uuid;
 p:=jsonb_build_object('id',gid,'revision',0,'name','Fictional fleet','organization','Confirmed company','reason','Fictional group');r:=public.fleet_command(w,dev,cid,'fleet_group',p);if r->>'saved'<>'true' then raise exception 'Group';end if;passed:=passed+1;
 if public.fleet_command(w,dev,cid,'fleet_group',p)<>r then raise exception 'Retry';end if;passed:=passed+1;
 failed:=false;begin perform public.fleet_command(w,dev,cid,'fleet_group',p||'{"name":"Changed"}');exception when others then failed:=true;end;if not failed then raise exception 'Changed retry';end if;passed:=passed+1;
 failed:=false;begin perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_group',p);exception when others then failed:=true;end;if not failed then raise exception 'Stale group';end if;passed:=passed+1;
 perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_group',p||'{"revision":1,"name":"Revised fleet"}');s:=public.device_snapshot(w,dev);if jsonb_array_length(s->'fleets'->'groups'->0->'versions')<>2 then raise exception 'Version history';end if;passed:=passed+1;
 p:=jsonb_build_object('id',gid,'revision',2,'membershipId',mid,'vehicleId',vid,'ownerId',owner,'reference','Unit 1','evidence','Confirmed fictional membership','reason','Fictional attachment');perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_attach',p);s:=public.device_snapshot(w,dev);if s->'fleets'->'groups'->0->'memberships'->0->>'ownerId'<>owner::text or s->'orders'->0<>before_order then raise exception 'Attachment or repair mutation';end if;passed:=passed+1;
 failed:=false;begin perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_attach',p||jsonb_build_object('revision',3,'membershipId',gen_random_uuid(),'ownerId',gen_random_uuid()));exception when others then failed:=true;end;if not failed then raise exception 'Foreign owner';end if;passed:=passed+1;
 failed:=false;begin perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_attach',p||jsonb_build_object('revision',3,'membershipId',gen_random_uuid(),'vehicleId',gen_random_uuid()));exception when others then failed:=true;end;if not failed then raise exception 'Foreign vehicle';end if;passed:=passed+1;
 perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_group',jsonb_build_object('id',gid2,'revision',3,'name','Second fleet','organization','Second company','reason','Transfer target'));
 failed:=false;begin perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_attach',p||jsonb_build_object('id',gid2,'revision',4,'membershipId',mid2));exception when others then failed:=true;end;if not failed then raise exception 'Duplicate active vehicle';end if;passed:=passed+1;
 failed:=false;begin perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_archive',jsonb_build_object('id',gid,'revision',4,'reason','Premature archive'));exception when others then failed:=true;end;if not failed then raise exception 'Archived active membership';end if;passed:=passed+1;
 perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_detach',jsonb_build_object('id',gid,'revision',4,'membershipId',mid,'reason','Transfer checked'));perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_attach',p||jsonb_build_object('id',gid2,'revision',5,'membershipId',mid2));s:=public.device_snapshot(w,dev);if jsonb_array_length(s->'fleets'->'groups')<>2 then raise exception 'Transfer lost history';end if;passed:=passed+1;
 perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_archive',jsonb_build_object('id',gid,'revision',6,'reason','Archive original'));
 failed:=false;begin perform public.fleet_command(w,dev,gen_random_uuid(),'fleet_group',jsonb_build_object('id',gid,'revision',7,'name','Reopen','organization','Company','reason','Invalid'));exception when others then failed:=true;end;if not failed then raise exception 'Archived fleet overwritten';end if;passed:=passed+1;
 update private.vehicle_profiles set owner_id=gen_random_uuid(),owner_data='{"name":"Fictional new owner","phone":""}' where workshop_id=w and vehicle_id=vid;s:=public.device_snapshot(w,dev);if s->'fleets'->'groups'->0->'memberships'->0->>'ownerId'<>owner::text then raise exception 'Original owner overwritten';end if;passed:=passed+1;
 perform set_config('request.jwt.claim.sub',t::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',t,'session_id',ts)::text,true);s:=public.device_snapshot(w,td);if s->'fleets'<>'{"revision":0,"groups":[]}'::jsonb then raise exception 'Technician privacy';end if;passed:=passed+1;
 failed:=false;begin perform public.fleet_command(w,td,gen_random_uuid(),'fleet_group',p);exception when others then failed:=true;end;if not failed then raise exception 'Technician wrote';end if;passed:=passed+1;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sid)::text,true);s:=public.workshop_snapshot(other);if jsonb_array_length(s->'fleets'->'groups')<>0 then raise exception 'Workshop isolation';end if;passed:=passed+1;
 if has_table_privilege('authenticated','private.fleet_state','select') or has_function_privilege('anon','public.fleet_command(uuid,uuid,uuid,text,jsonb)','execute') then raise exception 'Direct access';end if;passed:=passed+1;
 r:=public.export_workshop(w,dev);if r->>'databaseVersion'<>'13' or jsonb_array_length(r->'tables'->'fleet_state')<>1 then raise exception 'Archive';end if;perform private.validate_fleets(w,r->'tables'->'fleet_state'->0->'data');passed:=passed+1;
 perform set_config('tallerflow.fleet_checks',passed::text,true);
end $$;
select current_setting('tallerflow.fleet_checks')::int as checks_passed,'Hosted PostgreSQL; synthetic Auth; full rollback' as scope;
rollback;
